function sprFrame(S,u){const M=S.meta,t=u.anim||0;
  if(u.casting){const p=1-u.casting.t/u.casting.T;return p<.75?M.charge[Math.min(M.charge.length-1,Math.floor(p/.75*M.charge.length))]:M.fire[Math.floor(t*8)%M.fire.length];}
  if(u.atk>0)return M.atk[u.atk>.11?0:1];
  if(u.hitFl>.05&&!u.moving)return M.hurt[0];
  if(u.moving)return u.fly?M.fly[0]:M.run[Math.floor(t*10)%M.run.length];
  return M.idle[Math.floor(t*6)%M.idle.length];}
